code.C:
#include <stdio.h>
#include <string.h>
int main() {
    char s[105]; if (scanf("%s", s) != 1) return 0;
    char *p = s;
    if (strlen(s) == 12 && s[0] == '9' && s[1] == '1') p = s + 2;
    printf("%s", p + 5);
    for (int i = 0; i < 5; i++) putchar(p[i]);
    putchar('\n');
    return 0;
}

code.C++:
#include <iostream>
#include <string>
using namespace std;
int main() {
    string s; if (!(cin >> s)) return 0;
    if (s.length() == 12 && s.rfind("91", 0) == 0) s = s.substr(2);
    cout << s.substr(5) << s.substr(0, 5) << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s = sc.next();
            if (s.length() == 12 && s.startsWith("91")) s = s.substring(2);
            System.out.println(s.substring(5) + s.substring(0, 5));
        }
    }
}

